export const MAX_REWRITE_WORDS = 8_000;
export const MAX_FILE_BYTES = Math.floor(3.2 * 1024 * 1024);
export const GUEST_PROMO_CREDITS = 2;
export const SIGNUP_PROMO_CREDITS = 3;
export const GUEST_COOKIE_MAX_AGE_SECONDS = 365 * 24 * 60 * 60;

export type BillableInputKind = "text" | "txt" | "docx" | "png" | "jpeg";

export function countWords(text: string) {
  const trimmed = text.trim();
  return trimmed ? trimmed.split(/\s+/u).filter(Boolean).length : 0;
}

export function creditCostForWords(words: number) {
  if (!Number.isFinite(words) || words < 0) throw new Error("Word count must be a non-negative finite number.");
  return Math.max(1, Math.ceil(words / 1_000));
}

export function creditCostForText(text: string) {
  return creditCostForWords(countWords(text));
}

export function creditCostForInput(kind: BillableInputKind, text?: string) {
  if (kind === "text" || kind === "txt") return creditCostForText(text ?? "");
  return 1;
}

export function validateRewriteWordCount(text: string) {
  const words = countWords(text);
  return { words, ok: words <= MAX_REWRITE_WORDS };
}

export function isAcceptedFileKind(name: string, mimeType = "") {
  const lower = name.toLowerCase();
  const mime = mimeType.toLowerCase();
  if (lower.endsWith(".docx")) return "docx" as const;
  if (lower.endsWith(".png") || mime === "image/png") return "png" as const;
  if (lower.endsWith(".jpg") || lower.endsWith(".jpeg") || mime === "image/jpeg") return "jpeg" as const;
  if (lower.endsWith(".txt") || mime === "text/plain") return "txt" as const;
  return null;
}

export function validateFileSize(bytes: number) {
  return Number.isFinite(bytes) && bytes >= 0 && bytes <= MAX_FILE_BYTES;
}

import { latin1 } from "./binary";
import type { FileFinding } from "./types";

export function inspectPdf(bytes: Uint8Array): FileFinding[] {
  const text = latin1(bytes);
  const findings: FileFinding[] = [];
  const add = (id: string, kind: FileFinding["kind"], label: string, description: string, disposition: FileFinding["disposition"] = "privacy_metadata") => {
    findings.push({ id, kind, label, description, disposition, removableByDefault: false });
  };

  const infoKeys = ["Author", "Creator", "Producer", "CreationDate", "ModDate", "Title", "Subject", "Keywords"];
  const present = infoKeys.filter((key) => new RegExp(`\\/${key}\\s*(?:\\(|<)`, "m").test(text));
  if (present.length) add("pdf-info", "pdf_info", "PDF document information", `Document Info fields detected: ${present.join(", ")}. PDF rewriting is inspection-only in this phase to avoid corrupting signed or structurally complex files.`);

  if (/<x:xmpmeta\b|<rdf:RDF\b|adobe:ns:meta\//i.test(text)) {
    add("pdf-xmp", "pdf_xmp", "PDF XMP packet", "Embedded XMP metadata detected. Inspection-only until the PDF rewrite path can preserve cross-reference integrity.");
  }

  if (/c2pa|jumbf|contentauth|content credentials/i.test(text)) {
    add("pdf-provenance", "provenance_manifest", "Potential provenance manifest", "Potential signed provenance markers detected. These are never removed by default.", "provenance");
  }

  return findings;
}

const DEFAULT_MAX_CHARS = 5200;

function splitOversizedBlock(block: string, maxChars: number) {
  if (block.length <= maxChars) return [block];
  const sentences = block.split(/(?<=[.!?])\s+/);
  const chunks: string[] = [];
  let current = "";
  for (const sentence of sentences) {
    if (!sentence) continue;
    if (current && current.length + 1 + sentence.length > maxChars) {
      chunks.push(current);
      current = sentence;
    } else {
      current += `${current ? " " : ""}${sentence}`;
    }
  }
  if (current) chunks.push(current);
  return chunks.length ? chunks : [block];
}

export function chunkProtectedText(text: string, maxChars = DEFAULT_MAX_CHARS) {
  if (text.length <= maxChars) return [text];

  const blocks = text.split(/\n\s*\n/).flatMap((block) => splitOversizedBlock(block, maxChars));
  const chunks: string[] = [];
  let current = "";

  for (const block of blocks) {
    if (!block) continue;
    if (current && current.length + 2 + block.length > maxChars) {
      chunks.push(current);
      current = block;
    } else {
      current += `${current ? "\n\n" : ""}${block}`;
    }
  }
  if (current) chunks.push(current);
  return chunks;
}

